package ai.learnharness.mobile;
import android.app.Instrumentation;import android.content.*;import android.os.*;import android.view.accessibility.AccessibilityNodeInfo;import android.webkit.WebView;import org.json.*;import java.io.*;import java.lang.reflect.Field;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.concurrent.*;
/** Actual SAF tree picker and original provider note operations; isolated emulator only. */
final class SubjectFolderTest {
 private final Instrumentation test;private Context app;private WebView web;private JSONObject runtime;private final String phase;
 SubjectFolderTest(Instrumentation test,String phase){this.test=test;this.phase=phase;}
 void run()throws Exception{check(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"),"Disposable emulator required");app=test.getTargetContext();Intent intent=app.getPackageManager().getLaunchIntentForPackage(app.getPackageName());intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);MainActivity activity=(MainActivity)test.startActivitySync(intent);Field field=MainActivity.class.getDeclaredField("web");field.setAccessible(true);web=(WebView)field.get(activity);
 long until=SystemClock.elapsedRealtime()+180000;while(SystemClock.elapsedRealtime()<until){try{runtime=new JSONObject(new String(Files.readAllBytes(new File(app.getNoBackupFilesDir(),"runtime-info.json").toPath()),StandardCharsets.UTF_8));if(api("/api/subjects",null).has("subjects"))break;}catch(Exception ignored){}SystemClock.sleep(200);}check(runtime!=null,"Subject runtime started");for(int i=0;i<100;i++){try{api("/api/sync",new JSONObject().put("op","leave-library"));break;}catch(IOException busy){if(!busy.getMessage().contains("Wait"))throw busy;SystemClock.sleep(200);}}
 File savedFile=new File(app.getNoBackupFilesDir(),"subject-qa-state.json");
 if(!phase.equals("first")&&!phase.equals("relink")){JSONObject saved=new JSONObject(new String(Files.readAllBytes(savedFile.toPath()),StandardCharsets.UTF_8));if(phase.equals("revoke")){JSONObject grants=new JSONObject(new String(Files.readAllBytes(new File(app.getNoBackupFilesDir(),"document-grants.json").toPath()),StandardCharsets.UTF_8));android.net.Uri uri=android.net.Uri.parse(grants.getJSONObject(saved.getString("handle")).getString("uri"));app.getContentResolver().releasePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);return;}JSONObject read=api("/api/subjects?id="+saved.getString("workspaceId")+"&noteId="+saved.getString("noteId"),null);check(read.getString("text").contains("Practise transport questions."),"Cached/original note survives restart");if(phase.equals("revoked"))check(read.has("error"),"Revoked tree permission is actionable without losing cache");else check(!read.has("error"),"Persisted tree grant survives process restart");return;}
for(int i=0;i<150&&!js("Boolean(window.lh?.documents?.pick)").equals("true");i++)SystemClock.sleep(200);check(js("Boolean(window.lh?.documents?.pick)").equals("true"),"Native folder bridge ready");
 test.runOnMainSync(()->web.evaluateJavascript("window.__subjectPick=null;window.lh.documents.pick('folder').then(p=>window.__subjectPick=p);true",null));boolean chosen=false,providerSelected=false,subjectSelected=false,submitted=false;
 for(int i=0;i<100;i++){AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(submitted&&root!=null&&root.getPackageName()!=null&&root.getPackageName().toString().equals(app.getPackageName())){chosen=true;break;}if(click(root,"Allow")){submitted=true;}else if(!providerSelected){if(click(root,"LearnHarness QA"))providerSelected=true;else if(i%4==0)click(root,"Show roots");}else if(!subjectSelected){if(click(root,"Chinese subject"))subjectSelected=true;}else if(click(root,"Use this folder"))submitted=true;SystemClock.sleep(250);}
 check(chosen,"Native tree picker returned a folder grant");JSONObject picked=null;for(int i=0;i<50;i++){String value=js("window.__subjectPick");if(value!=null&&value.startsWith("{")){picked=new JSONObject(value);break;}SystemClock.sleep(200);}check(picked!=null,"Native tree grant returned after picker dismissal");check(picked.optBoolean("persisted"),"Tree permission persisted");JSONObject preview=api("/api/subjects",new JSONObject().put("op","preview").put("folder",picked));check(preview.getJSONArray("paths").length()>=3,"Subject notes enumerated through ContentResolver");
 JSONObject linkRequest=new JSONObject().put("op","link").put("previewId",preview.getString("previewId")).put("name","SAF Chinese subject QA").put("mode","external").put("included",preview.getJSONArray("paths"));JSONObject previous=phase.equals("relink")?new JSONObject(new String(Files.readAllBytes(savedFile.toPath()),StandardCharsets.UTF_8)):null;if(previous!=null)linkRequest.put("workspaceId",previous.getString("workspaceId"));JSONObject linked=api("/api/subjects",linkRequest);String workspace=linked.getString("id");JSONObject detail=null;for(int i=0;i<200;i++){detail=api("/api/subjects?id="+workspace,null);if(!detail.getJSONObject("subject").getJSONObject("scan").getString("phase").equals("scanning"))break;SystemClock.sleep(100);}check(detail.getJSONObject("subject").getJSONArray("notes").length()>=3,"Native originals indexed");
 JSONObject chat=api("/api/chats",new JSONObject().put("title","Subject SAF test"));String chatId=chat.getString("id");api("/api/subjects",new JSONObject().put("op","associate").put("workspaceId",workspace).put("chatId",chatId));JSONObject note=detail.getJSONObject("subject").getJSONArray("notes").getJSONObject(0);String noteId=note.getString("id");Files.write(savedFile.toPath(),new JSONObject().put("workspaceId",workspace).put("noteId",noteId).put("handle",picked.getString("handle")).toString().getBytes(StandardCharsets.UTF_8));if(previous!=null)check(previous.getString("workspaceId").equals(workspace)&&previous.getString("noteId").equals(noteId),"Relink preserves workspace and original-note identity");JSONObject read=api("/api/subjects?id="+workspace+"&noteId="+noteId+"&chatId="+chatId,null);check(read.getString("text").contains("Practise transport questions."),"Original tree child read");
 JSONObject doc=api("/api/documents?id="+noteId,null);check(!doc.getJSONObject("document").getBoolean("logging"),"Folder discovery does not enable live logging");JSONObject proposal=api("/api/documents",new JSONObject().put("op","propose").put("documentId",noteId).put("chatId",chatId).put("baseRevision",read.getString("revision")).put("before","Practise transport questions.").put("after","Review 你怎么去医院？ next lesson."));
 api("/api/documents",new JSONObject().put("op","review").put("documentId",noteId).put("proposalId",proposal.getString("id")).put("action","apply"));check(api("/api/subjects?id="+workspace+"&noteId="+noteId,null).getString("text").contains("你怎么去医院"),"Reviewed edit wrote the original provider child");api("/api/documents",new JSONObject().put("op","review").put("documentId",noteId).put("proposalId",proposal.getString("id")).put("action","undo"));check(api("/api/subjects?id="+workspace+"&noteId="+noteId,null).getString("text").equals(read.getString("text")),"Undo restored original child");
 }
 private boolean click(AccessibilityNodeInfo node,String text){if(node==null)return false;String actual=node.getText()==null?"":node.getText().toString();if(actual.equalsIgnoreCase(text)||node.getContentDescription()!=null&&node.getContentDescription().toString().equalsIgnoreCase(text)){AccessibilityNodeInfo p=node;while(p!=null){if(p.isClickable())return p.performAction(AccessibilityNodeInfo.ACTION_CLICK);p=p.getParent();}}for(int i=0;i<node.getChildCount();i++)if(click(node.getChild(i),text))return true;return false;}
 private String js(String code)throws Exception{String[] value={null};CountDownLatch done=new CountDownLatch(1);test.runOnMainSync(()->web.evaluateJavascript(code,v->{value[0]=v;done.countDown();}));check(done.await(30,TimeUnit.SECONDS),"WebView response");return value[0];}
 private JSONObject api(String route,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+runtime.getInt("port")+route).openConnection();c.setConnectTimeout(3000);c.setReadTimeout(60000);c.setRequestProperty("x-learnharness-android",runtime.getString("token"));c.setRequestProperty("Origin","http://127.0.0.1:"+runtime.getInt("port"));try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();try(InputStream in=status<400?c.getInputStream():c.getErrorStream()){JSONObject result=new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));if(status>=400)throw new IOException(result.optString("error","API failed"));return result;}}finally{c.disconnect();}}
 private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
}
